// Splits the sales rows into "this week" (the 7 days before today) and "last week"
// (the 7 days before that), then compares them. Money is summed in integer cents.
// Rows with a bad date or amount are skipped and counted, so the report can say so.
// Expected columns: Date, Order ID, Customer, Product, Region, Quantity, Amount, Status

const settings = $('Report settings').first().json;
const rows = $input.all().map((i) => i.json);

// Today, or a fixed end date for re-running an old week.
const end = (settings.reportEndDate ? DateTime.fromISO(settings.reportEndDate) : $now).startOf('day');
const thisStart = end.minus({ days: 7 });
const lastStart = end.minus({ days: 14 });

const toCents = (raw) => {
  const clean = String(raw ?? '').replace(/[\s,$€£]/g, '');
  const m = clean.match(/^(-?)(\d+)(?:\.(\d{1,2}))?$/);
  if (!m) return null;
  const cents = Number(m[2]) * 100 + Number((m[3] ?? '').padEnd(2, '0'));
  return m[1] ? -cents : cents;
};
const parseDate = (raw) => {
  const s = String(raw ?? '').trim();
  for (const d of [DateTime.fromISO(s), DateTime.fromFormat(s, 'M/d/yyyy'), DateTime.fromFormat(s, 'd.M.yyyy')]) {
    if (d.isValid) return d.startOf('day');
  }
  return null;
};

const empty = () => ({ revenue: 0, refunds: 0, orders: 0, units: 0, customers: new Set(), products: {}, regions: {}, days: {} });
const periods = { current: empty(), previous: empty() };
const firstSeen = {}; // customer -> first date in the whole sheet
let skipped = 0;

for (const row of rows) {
  if (!row || Object.keys(row).length === 0) continue;
  const date = parseDate(row.Date);
  const cents = toCents(row.Amount);
  if (!date || cents === null) {
    skipped += 1;
    continue;
  }
  const customer = String(row.Customer ?? '').trim() || 'Unknown';
  const iso = date.toISODate();
  if (!firstSeen[customer] || iso < firstSeen[customer]) firstSeen[customer] = iso;

  const key = date >= thisStart && date < end ? 'current' : date >= lastStart && date < thisStart ? 'previous' : null;
  if (!key) continue;
  const p = periods[key];

  if (String(row.Status ?? '').trim().toLowerCase() === 'refunded') {
    p.refunds += Math.abs(cents);
    continue;
  }
  const qty = Number(row.Quantity) || 0;
  const product = String(row.Product ?? '').trim() || 'Other';
  const region = String(row.Region ?? '').trim() || 'Other';
  p.revenue += cents;
  p.orders += 1;
  p.units += qty;
  p.customers.add(customer);
  p.products[product] = p.products[product] ?? { revenue: 0, units: 0 };
  p.products[product].revenue += cents;
  p.products[product].units += qty;
  p.regions[region] = (p.regions[region] ?? 0) + cents;
  p.days[iso] = (p.days[iso] ?? 0) + cents;
}

const summarize = (p) => ({
  revenueCents: p.revenue,
  refundsCents: p.refunds,
  netCents: p.revenue - p.refunds,
  orders: p.orders,
  units: p.units,
  customers: p.customers.size,
  avgOrderCents: p.orders ? Math.round(p.revenue / p.orders) : 0,
});
const current = summarize(periods.current);
const previous = summarize(periods.previous);

const change = (now, before) => (before === 0 ? null : Math.round(((now - before) / before) * 1000) / 10);
const changes = {};
for (const k of Object.keys(current)) changes[k] = change(current[k], previous[k]);

const newCustomers = [...periods.current.customers].filter((c) => firstSeen[c] >= thisStart.toISODate()).length;
const topN = Number(settings.topProducts) || 5;
const topProducts = Object.entries(periods.current.products)
  .map(([name, v]) => ({
    name,
    revenueCents: v.revenue,
    units: v.units,
    previousRevenueCents: periods.previous.products[name]?.revenue ?? 0,
  }))
  .sort((a, b) => b.revenueCents - a.revenueCents)
  .slice(0, topN);
const regions = Object.entries(periods.current.regions)
  .map(([name, cents]) => ({ name, revenueCents: cents, previousRevenueCents: periods.previous.regions[name] ?? 0 }))
  .sort((a, b) => b.revenueCents - a.revenueCents);
const daily = [];
for (let d = thisStart; d < end; d = d.plus({ days: 1 })) {
  daily.push({ date: d.toISODate(), weekday: d.toFormat('ccc'), revenueCents: periods.current.days[d.toISODate()] ?? 0 });
}

return [
  {
    json: {
      hasData: current.orders > 0,
      currency: String(settings.currency || 'USD').toUpperCase(),
      periodStart: thisStart.toISODate(),
      periodEnd: end.minus({ days: 1 }).toISODate(),
      previousStart: lastStart.toISODate(),
      previousEnd: thisStart.minus({ days: 1 }).toISODate(),
      current,
      previous,
      changes,
      newCustomers,
      topProducts,
      regions,
      daily,
      rowsRead: rows.length,
      rowsSkipped: skipped,
    },
  },
];

// Builds the Markdown report: KPI table, the AI summary, top products, regions and a daily table.
// If the AI step failed or returned nothing, a plain fallback summary is used, so the report still goes out.

const settings = $('Report settings').first().json;
const m = $('Compare this week with last week').first().json;
const c = m.currency;

const money = (cents) => {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const whole = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${sign}${c} ${whole}.${String(abs % 100).padStart(2, '0')}`;
};
const pct = (v) => (v === null || v === undefined ? 'new' : `${v > 0 ? '+' : ''}${v.toFixed(1)}%`);
const delta = (now, before) => (before === 0 ? 'new' : pct(Math.round(((now - before) / before) * 1000) / 10));
// Keep table cells and AI text from breaking the layout or injecting HTML.
const cell = (v) => String(v ?? '').replace(/[<>]/g, '').replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
const safe = (v) => String(v ?? '').replace(/[<>]/g, '');

let summary = safe($json.text).trim();
if (!summary) {
  summary =
    `- Net revenue was ${money(m.current.netCents)} (${pct(m.changes.netCents)} on last week) from ${m.current.orders} orders.\n` +
    `- Average order value was ${money(m.current.avgOrderCents)} (${pct(m.changes.avgOrderCents)}).\n` +
    `- Top product: ${m.topProducts[0]?.name ?? 'none'}.\n\n` +
    '_The AI summary was not available this week, so this short summary was built from the numbers._';
}

const L = [];
L.push(`# ${cell(settings.reportTitle)}`);
L.push('');
L.push(`**${cell(settings.companyName)}** | ${m.periodStart} to ${m.periodEnd} | compared with ${m.previousStart} to ${m.previousEnd}`);
L.push('');
L.push(
  `_Source: ${m.rowsRead} rows from the sales sheet.` +
    (m.rowsSkipped ? ` ${m.rowsSkipped} rows were skipped because the date or amount could not be read.` : ' All rows could be read.') +
    ` Generated ${$now.toFormat('d LLL yyyy, HH:mm')} (${$now.zoneName}). Refunds count in the week they appear in the sheet._`,
);
L.push('');
L.push('## Key numbers');
L.push('');
L.push('| Metric | This week | Last week | Change |');
L.push('|---|---:|---:|---:|');
const kpi = [
  ['Gross revenue', 'revenueCents', money],
  ['Refunds', 'refundsCents', money],
  ['Net revenue', 'netCents', money],
  ['Orders', 'orders', String],
  ['Units sold', 'units', String],
  ['Customers', 'customers', String],
  ['Average order value', 'avgOrderCents', money],
];
for (const [label, key, fmt] of kpi) {
  L.push(`| ${label} | ${fmt(m.current[key])} | ${fmt(m.previous[key])} | ${pct(m.changes[key])} |`);
}
L.push(`| New customers | ${m.newCustomers} | | |`);
L.push('');
L.push('## Executive summary');
L.push('');
L.push(summary);
L.push('');
L.push(`## Top ${m.topProducts.length} products`);
L.push('');
L.push('| Product | Units | Revenue | Last week | Change |');
L.push('|---|---:|---:|---:|---:|');
for (const p of m.topProducts) {
  L.push(`| ${cell(p.name)} | ${p.units} | ${money(p.revenueCents)} | ${money(p.previousRevenueCents)} | ${delta(p.revenueCents, p.previousRevenueCents)} |`);
}
L.push('');
L.push('## Revenue by region');
L.push('');
L.push('| Region | Revenue | Share | Last week | Change |');
L.push('|---|---:|---:|---:|---:|');
for (const r of m.regions) {
  const share = m.current.revenueCents ? ((r.revenueCents / m.current.revenueCents) * 100).toFixed(1) + '%' : '';
  L.push(`| ${cell(r.name)} | ${money(r.revenueCents)} | ${share} | ${money(r.previousRevenueCents)} | ${delta(r.revenueCents, r.previousRevenueCents)} |`);
}
L.push('');
L.push('## Revenue by day');
L.push('');
L.push('| Day | Date | Revenue |');
L.push('|---|---|---:|');
for (const d of m.daily) L.push(`| ${d.weekday} | ${d.date} | ${money(d.revenueCents)} |`);
L.push('');
const headline = `Net revenue ${money(m.current.netCents)} (${pct(m.changes.netCents)} vs last week), ${m.current.orders} orders`;

return [
  {
    json: {
      markdown: L.join('\n'),
      fileName: `sales-report-${m.periodEnd}.pdf`,
      period: `${m.periodStart} to ${m.periodEnd}`,
      headline,
    },
  },
];
